#include <iostream>
#include <string>

constexpr int LEFT_TEXT   = 0;
constexpr int CENTER_TEXT = 1;
constexpr int RIGHT_TEXT  = 2;

constexpr int BOTTOM_TEXT = 0;
constexpr int CENTER_VERT = 1;
constexpr int TOP_TEXT    = 2;

struct Rect {
    int x1, y1, x2, y2;
};

Rect computeTextBounds(int anchorX, int anchorY, const std::string& text,
                       int charW, int charH, int horizJust, int vertJust) {
    int w = static_cast<int>(text.length()) * charW;
    int h = charH;
    int left = 0;
    if (horizJust == LEFT_TEXT) left = anchorX;
    else if (horizJust == CENTER_TEXT) left = anchorX - w / 2;
    else if (horizJust == RIGHT_TEXT)  left = anchorX - w;

    int top = 0;
    if (vertJust == TOP_TEXT) top = anchorY;
    else if (vertJust == CENTER_VERT) top = anchorY - h / 2;
    else if (vertJust == BOTTOM_TEXT) top = anchorY - h;

    return {left, top, left + w, top + h};
}

int main() {
    int anchorX = 320, anchorY = 240;
    std::string sample = "Triplex";
    int charW = 16, charH = 24;

    Rect rCenter = computeTextBounds(anchorX, anchorY, sample, charW, charH, CENTER_TEXT, CENTER_VERT);
    Rect rLeft   = computeTextBounds(anchorX, anchorY, sample, charW, charH, LEFT_TEXT, TOP_TEXT);

    std::cout << "Text: '" << sample << "' (size: " << sample.length() * charW << "x" << charH << ")\n";
    std::cout << "Anchor: (" << anchorX << ", " << anchorY << ")\n";
    std::cout << "[CENTER_TEXT, CENTER_VERT] -> [" << rCenter.x1 << ", " << rCenter.y1
              << "] to [" << rCenter.x2 << ", " << rCenter.y2 << "]\n";
    std::cout << "[LEFT_TEXT, TOP_TEXT]         -> [" << rLeft.x1 << ", " << rLeft.y1
              << "] to [" << rLeft.x2 << ", " << rLeft.y2 << "]\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <cstdint>
#include <iomanip>

enum RasterOp { COPY_PUT = 0, XOR_PUT = 1, OR_PUT = 2, AND_PUT = 3 };

void applyRasterOp(std::vector<uint8_t>& target, const std::vector<uint8_t>& sprite, RasterOp op) {
    for (size_t i = 0; i < target.size(); ++i) {
        switch (op) {
            case COPY_PUT: target[i] = sprite[i]; break;
            case XOR_PUT:  target[i] ^= sprite[i]; break;
            case OR_PUT:   target[i] |= sprite[i]; break;
            case AND_PUT:  target[i] &= sprite[i]; break;
        }
    }
}

int main() {
    std::vector<uint8_t> screenBuffer = {0xAA, 0x55, 0xFF, 0x00};
    const std::vector<uint8_t> sprite = {0x0F, 0xF0, 0xAA, 0x55};

    std::cout << "Initial screen buffer: ";
    for (auto b : screenBuffer) std::cout << std::hex << std::setw(2) << std::setfill('0') << (int)b << " ";
    std::cout << "\n";

    // Frame 1: Draw sprite using XOR
    applyRasterOp(screenBuffer, sprite, XOR_PUT);
    std::cout << "After 1st XOR blit:   ";
    for (auto b : screenBuffer) std::cout << std::hex << std::setw(2) << std::setfill('0') << (int)b << " ";
    std::cout << "\n";

    // Frame 2: Draw identical sprite at same place using XOR -> Background is restored!
    applyRasterOp(screenBuffer, sprite, XOR_PUT);
    std::cout << "After 2nd XOR blit:   ";
    for (auto b : screenBuffer) std::cout << std::hex << std::setw(2) << std::setfill('0') << (int)b << " ";
    std::cout << " (Restored)\n";

    return 0;
}

#include <iostream>
#include <cmath>
#include <vector>
#include <iomanip>

constexpr double PI = 3.14159265358979323846;

struct Point {
    int x, y;
};

struct SpokeLine {
    Point p1, p2;
};

std::vector<SpokeLine> computeWheelSpokes(int cx, int cy, int r, double phi) {
    std::vector<SpokeLine> spokes;
    spokes.reserve(6);
    double currentAngle = phi;
    for (int i = 0; i < 6; ++i) {
        int x1 = cx + static_cast<int>(r * std::cos(currentAngle));
        int y1 = cy - static_cast<int>(r * std::sin(currentAngle));
        int x2 = cx - static_cast<int>(r * std::cos(currentAngle));
        int y2 = cy + static_cast<int>(r * std::sin(currentAngle));
        spokes.push_back({ {x1, y1}, {x2, y2} });
        currentAngle += PI / 3.0; // 60 degrees apart
    }
    return spokes;
}

int main() {
    int x = 100, y = 200, r = 50;
    double phi = 0.0;
    double dPhi = PI / 72.0;

    std::cout << "Rolling Wheel Kinematic Simulation (3 frames):\n";
    for (int frame = 0; frame < 3; ++frame) {
        auto spokes = computeWheelSpokes(x, y, r, phi);
        std::cout << "Frame " << frame << " | Center: (" << x << ", " << y << ")"
                  << " | Angle: " << std::fixed << std::setprecision(3) << phi << " rad"
                  << " | Spoke[0]: [(" << spokes[0].p1.x << ", " << spokes[0].p1.y
                  << ") -> (" << spokes[0].p2.x << ", " << spokes[0].p2.y << ")]\n";
        // Step update: translate rightwards and rotate clockwise
        x += 5;
        phi -= dPhi;
    }
    return 0;
}
